```go
package main

import "fmt"

type User struct {
    Name   string
    Active bool
}

func (u User) Label() string {
    return fmt.Sprintf("%s active=%t", u.Name, u.Active)
}

func main() {
    var empty User
    named := User{Name: "Asha", Active: true}
    fmt.Println(empty.Label())
    fmt.Println(named.Label())
}
```
The first line uses the field zero values; the second uses a keyed struct literal. Both are complete `User` values.

```go
package main

import "fmt"

type Stats struct {
    Requests int
    Labels   map[string]string
}

func (s *Stats) AddLabel(key, value string) {
    if s.Labels == nil {
        s.Labels = make(map[string]string)
    }
    s.Labels[key] = value
}

func main() {
    var stats Stats
    stats.Requests++
    stats.AddLabel("env", "test")
    fmt.Println(stats.Requests, stats.Labels["env"])
}
```
`Requests` needs no setup. The method allocates the map only before its first write, so the whole struct remains useful from its zero value.

```go
package main

import "fmt"

type UserKey struct {
    Tenant string
    ID     int
}

func main() {
    first := UserKey{Tenant: "acme", ID: 7}
    second := UserKey{Tenant: "acme", ID: 7}
    owners := map[UserKey]string{first: "Mina"}
    fmt.Println(first == second, owners[second])
}
```
The output is `true Mina`. Both fields are comparable, so equality and map-key lookup use the complete struct value.
